-- Safe additive migration for an existing GrowReview CRM V1/V3 database.
-- It does not drop or alter the existing review, customer, staff or business tables.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,monthly_price INT NOT NULL,features_json JSON DEFAULT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO plans(code,name,monthly_price,features_json) VALUES ('basic','Basic',2999,JSON_ARRAY('Branded QR page','AI reviews','Staff attribution','Basic CRM')),('growth','Growth',4999,JSON_ARRAY('Basic features','GMB Growth Studio','Photo plans','Services optimizer','Advanced reports')),('maximizer_pro','Maximizer Pro',9999,JSON_ARRAY('Growth features','Multi-location ready','Auto-post scheduler','Google API actions','Priority support')) ON DUPLICATE KEY UPDATE name=VALUES(name),monthly_price=VALUES(monthly_price),features_json=VALUES(features_json);
CREATE TABLE IF NOT EXISTS business_subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,plan_id BIGINT UNSIGNED NOT NULL,status ENUM('active','trial','paused','cancelled') NOT NULL DEFAULT 'active',started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,renews_at DATETIME DEFAULT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_sub_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,CONSTRAINT fk_sub_plan FOREIGN KEY (plan_id) REFERENCES plans(id),UNIQUE KEY uq_business_subscription (business_id),INDEX idx_sub_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS gmb_connections (business_id BIGINT UNSIGNED PRIMARY KEY,account_id VARCHAR(120) DEFAULT NULL,location_id VARCHAR(160) DEFAULT NULL,category_id VARCHAR(180) DEFAULT NULL,is_enabled TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_gmb_connection_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS gmb_content_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,content_type ENUM('post','photo','service_sync','review_reply','plan') NOT NULL DEFAULT 'post',title VARCHAR(220) DEFAULT NULL,payload_json JSON NOT NULL,status ENUM('draft','scheduled','processing','published','failed') NOT NULL DEFAULT 'draft',scheduled_at DATETIME DEFAULT NULL,published_at DATETIME DEFAULT NULL,error_message TEXT DEFAULT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_gmb_job_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,INDEX idx_gmb_jobs_due (status,scheduled_at),INDEX idx_gmb_jobs_business (business_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
